package com.example.reporting;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.expression.ExpressionParser;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.expression.spel.support.StandardEvaluationContext;
import org.springframework.expression.Expression;
import java.util.Map;
import java.util.HashMap;

@SpringBootApplication
@RestController
@RequestMapping("/api/v2/reports")
public class ReportFilterApplication {

    private final ExpressionParser parser = new SpelExpressionParser();

    public static void main(String[] args) {
        SpringApplication.run(ReportFilterApplication.class, args);
    }

    // Internal report data store (simulated)
    private Map<String, Object> getReportContext() {
        Map<String, Object> ctx = new HashMap<>();
        ctx.put("revenue", 1500000);
        ctx.put("quarter", "Q3");
        ctx.put("region", "EMEA");
        ctx.put("headcount", 342);
        ctx.put("margin", 0.23);
        return ctx;
    }

    /**
     * Dynamic report filtering endpoint.
     * Accepts a SpEL filter expression to evaluate against report metrics.
     * Example: /api/v2/reports/filter?expr=revenue > 1000000
     */
    @GetMapping("/filter")
    public Map<String, Object> filterReport(@RequestParam("expr") String filterExpression) {
        StandardEvaluationContext context = new StandardEvaluationContext();
        Map<String, Object> reportData = getReportContext();

        // Set report variables into evaluation context
        for (Map.Entry<String, Object> entry : reportData.entrySet()) {
            context.setVariable(entry.getKey(), entry.getValue());
        }

        Map<String, Object> result = new HashMap<>();
        try {
            // Evaluate the user-provided expression
            Expression expression = parser.parseExpression(filterExpression);
            Object evalResult = expression.getValue(context);
            result.put("filter_result", evalResult);
            result.put("expression", filterExpression);
            result.put("status", "success");
        } catch (Exception e) {
            result.put("status", "error");
            result.put("message", e.getMessage());
        }
        return result;
    }

    /**
     * Batch evaluation endpoint for dashboard widgets.
     * Accepts multiple expressions separated by semicolons.
     */
    @PostMapping("/evaluate")
    public Map<String, Object> evaluateBatch(@RequestBody Map<String, String> request) {
        String expressions = request.getOrDefault("expressions", "");
        StandardEvaluationContext context = new StandardEvaluationContext();
        Map<String, Object> reportData = getReportContext();

        for (Map.Entry<String, Object> entry : reportData.entrySet()) {
            context.setVariable(entry.getKey(), entry.getValue());
        }

        Map<String, Object> results = new HashMap<>();
        String[] exprArray = expressions.split(";");
        int idx = 0;
        for (String expr : exprArray) {
            expr = expr.trim();
            if (expr.isEmpty()) continue;
            try {
                Expression expression = parser.parseExpression(expr);
                Object evalResult = expression.getValue(context);
                results.put("result_" + idx, evalResult);
            } catch (Exception e) {
                results.put("error_" + idx, e.getMessage());
            }
            idx++;
        }
        results.put("total_evaluated", idx);
        return results;
    }

    // Health check with version info
    @GetMapping("/health")
    public Map<String, String> health() {
        Map<String, String> h = new HashMap<>();
        h.put("status", "UP");
        h.put("version", "2.4.1");
        h.put("engine", "SpEL");
        return h;
    }
}
